class CUOAM21B(CUOAM19B):
    def __init__(self, con_details):
        super(CUOAM21B, self).__init__(con_details)
        self.fm_licensed = FMLICENSEDv1(con_details=con_details)
        self.cp_config_licensed = CPCONFIG_LICENSEDv1(con_details=con_details)
        self.asm_licensed = ASM_LICENSEDv1(con_details=con_details)
        self.trs = TRSv1(con_details=con_details)
        self.cm_licensed = CM_LICENSEDv1(con_details=con_details)
        self.agent = AGENTv1(con_details=con_details)

    def get_counter(self, _, dimension_dist_name, counter_id, timeout=30, start_time_lower_limit=None,
                    start_time_upper_limit=None, raw=False):
        values = self.pm_v2.get_counter(dimension_dist_name=dimension_dist_name, counter_id=counter_id,
                                        timeout=timeout, start_time_lower_limit=start_time_lower_limit,
                                        start_time_upper_limit=start_time_upper_limit)
        full_response = {"id": counter_id,
                         "dimension_dist_name": dimension_dist_name,
                         "measurement_id": None,
                         "values": list(values.values())[0]}
        return full_response if raw else CounterValuePMV2.from_object_dict(full_response)

