    def get_active_alarms(self, timeout=None, use_m2m=True, raw=False, **kwargs):
        if use_m2m:
            active_alarms = self.fm_licensed.get_active_alarms(timeout=timeout, **kwargs)
        else:
            active_alarms = self.fm.get_active_alarms(timeout=timeout, **kwargs)

        return active_alarms if raw else ActiveAlarmsLicensedV1.from_object_dict(active_alarms)

