    @enforce_use_m2m_type
    def get_cells_statuses(self, timeout=None, use_m2m=True, raw=False):
        if use_m2m:
            response = self.asm_licensed.get_cu_cells_diff(timeout=timeout)
        else:
            response = self.asm_v1.get_cu_cells_diff(timeout=timeout)

        if raw:
            return [cell["basicCell"] for cell in response["created"]]
        else:
            return [cell["basic_cell"] for cell in GetCellsStatusesv1.from_object_dict(response)["created"]]

