    @enforce_use_m2m_type
    def get_local_snapshot_by_id(self, directory, operation_id, request_timeout=None, operation_timeout=600.0, use_m2m=True,
                                 compressed=True):
        if use_m2m:
            return self.asm_licensed.get_local_snapshot_by_id(directory=directory,
                                                              operation_id=operation_id,
                                                              request_timeout=request_timeout,
                                                              operation_timeout=operation_timeout,
                                                              compressed=compressed)
        else:
            return self.asm_v1.get_local_snapshot_by_id(directory=directory,
                                                        operation_id=operation_id,
                                                        request_timeout=request_timeout,
                                                        operation_timeout=operation_timeout,
                                                        compressed=compressed)

    @enforce_use_m2m_type
    def get_local_snapshot(self, directory, request_timeout, operation_timeout, use_m2m=True, compressed=True):
        if use_m2m:
            return self.asm_licensed.get_local_snapshot(directory=directory,
                                                        request_timeout=request_timeout,
                                                        operation_timeout=operation_timeout,
                                                        compressed=compressed)
        else:
            return self.asm_v1.get_local_snapshot(directory=directory,
                                                  request_timeout=request_timeout,
                                                  operation_timeout=operation_timeout,
                                                  compressed=compressed)

    @enforce_use_m2m_type
    def get_current_plan_file(self, path, include_runtime_data, timeout, include_auto_config_data=True, use_m2m=True):
        if use_m2m:
            plan_file = self.cm_licensed.get_current_plan_content(include_runtime_data=include_runtime_data,
                                                                  timeout=timeout,
                                                                  include_auto_config_data=include_auto_config_data)
        else:
            plan_file = self.cm.get_current_plan_content(include_runtime_data=include_runtime_data,
                                                         timeout=timeout,
                                                         include_auto_config_data=include_auto_config_data)

        save_to_file(target_path=path, content=plan_file)

        return plan_file.decode('utf-8')

    def update_local_user_account(self, username, password, new_username, new_password, active_status):
        response = self.asm_v1.update_local_user_account(username=username,
                                                         password=password,
                                                         new_username=new_username,
                                                         new_password=new_password,
                                                         active_status=active_status)

        return LocalUserAccountUpadateResponse.from_object_dict(response)

